def largest_after_each(rows, cols, fills):
    parent = {}
    size = {}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    best = 0
    out = []
    for r, c in fills:
        cell = r * cols + c
        if cell not in parent:
            parent[cell] = cell
            size[cell] = 1
            for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= a < rows and 0 <= b < cols and a * cols + b in parent:
                    x, y = find(cell), find(a * cols + b)
                    if x != y:
                        if size[x] < size[y]:
                            x, y = y, x
                        parent[y] = x
                        size[x] += size[y]
            best = max(best, size[find(cell)])
        out.append(best)
    return out

