def largest_after_each(rows, cols, fills):
    land = set()
    best = 0
    out = []
    for r, c in fills:
        land.add((r, c))
        seen = {(r, c)}
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
